import type { SqliteHandle } from './database.js';

/**
 * What the loop learned from its own runs, one line per resolved run.
 *
 * The effectiveness table already counts how often an operation helped. A ratio is not a
 * lesson: it cannot say that a run drained nine rows and the depth was the same an hour later,
 * or that the operation failed on a store it could not reach. These rows carry the sentence,
 * and the sentence is what reaches the advisor's prompt.
 *
 * Nothing here is generated by a model. A lesson is the run's own numbers written out, so a
 * reader can check it against the ledger and a prompt cannot be fed something invented.
 */

export type IntrospectionInsight = {
  readonly id: number;
  readonly operation: string;
  readonly lesson: string;
  readonly recordedAt: string;
};

type InsightRow = {
  id: number;
  operation: string;
  lesson: string;
  recorded_at: string;
};

/**
 * How many rows the table keeps. The prompt reads a handful and nothing else reads the rest, so
 * the table is a window rather than an archive: the ledger is where a run's full record lives.
 */
export const INSIGHT_RETENTION_ROWS = 200;

export function appendIntrospectionInsight(
  db: SqliteHandle,
  insight: { readonly operation: string; readonly lesson: string; readonly recordedAt?: Date },
): void {
  db.transaction(() => {
    db.prepare(
      'INSERT INTO introspection_insights (operation, lesson, recorded_at) VALUES (?, ?, ?)',
    ).run(insight.operation, insight.lesson, (insight.recordedAt ?? new Date()).toISOString());
    db.prepare(
      `DELETE FROM introspection_insights WHERE id <= (
         SELECT max(id) - ? FROM introspection_insights
       )`,
    ).run(INSIGHT_RETENTION_ROWS);
  })();
}

/** The most recent lessons, oldest first, so a prompt reads them in the order they happened. */
export function listRecentInsights(
  db: SqliteHandle,
  limit: number,
): readonly IntrospectionInsight[] {
  if (limit <= 0) {
    return [];
  }
  const rows = db
    .prepare(
      `SELECT id, operation, lesson, recorded_at FROM introspection_insights
       ORDER BY id DESC LIMIT ?`,
    )
    .all(limit) as InsightRow[];
  return rows
    .map((row) => ({
      id: row.id,
      operation: row.operation,
      lesson: row.lesson,
      recordedAt: row.recorded_at,
    }))
    .reverse();
}
